pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        address deployer = address(this);
        vm.assume(newOwner != deployer);
        vm.prank(deployer);
        bool success = c.setOwner(newOwner);
        assertTrue(success && c.owner() == newOwner);
    }
}
